# ------------------------------------------------------------------ passwords / config
def hash_pw(pw, it=200000):
    salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac("sha256", pw.encode(), salt.encode(), it).hex()
    return "pbkdf2$%d$%s$%s" % (it, salt, h)

def check_pw(pw, stored):
    try:
        _, it, salt, h = stored.split("$")
        c = hashlib.pbkdf2_hmac("sha256", pw.encode(), salt.encode(), int(it)).hex()
        return hmac.compare_digest(c, h)
    except Exception:
        return False

