# ------------------------------------------------------------------ audit log (hash chained)
_last_hash = ["0" * 64]
RECENT = []

def audit(user, event, ip="-"):
    with LOCK:
        rec = {"t": round(time.time(), 3), "u": user, "e": event, "ip": ip}
        line = json.dumps(rec, ensure_ascii=False, separators=(",", ":"))
        h = hashlib.sha256((_last_hash[0] + line).encode()).hexdigest()
        _last_hash[0] = h
        with open(AUDIT_PATH, "a", encoding="utf-8") as f: f.write(line + "\t" + h + "\n")
        RECENT.insert(0, rec); del RECENT[200:]

def init_audit():
    if os.path.exists(AUDIT_PATH):
        for ln in open(AUDIT_PATH, encoding="utf-8"):
            if "\t" in ln:
                a, h = ln.rstrip("\n").rsplit("\t", 1); _last_hash[0] = h
                try: RECENT.insert(0, json.loads(a))
                except Exception: pass
        del RECENT[200:]

def verify_audit():
    prev, n = "0" * 64, 0
    for ln in open(AUDIT_PATH, encoding="utf-8"):
        a, h = ln.rstrip("\n").rsplit("\t", 1)
        if hashlib.sha256((prev + a).encode()).hexdigest() != h:
            print("TAMPERING DETECTED at record", n + 1); return 1
        prev, n = h, n + 1
    print("Audit log OK, %d records" % n); return 0

# ------------------------------------------------------------------ meter model + simulator
def kv_of(n):
    n = n.lower()
    if "132" in n: return 132
    if re.search(r"33 ?kv", n): return 33
    if "3.3" in n: return 3.3
    if re.search(r"\blt\b|aux|colony|guest|workshop|ground|ups|control|pump house|panel|dtp", n): return .415
    return 11

def base_of(n, r):
    n = n.lower(); m = re.search(r"(\d+(?:\.\d+)?) ?mva", n); k = re.search(r"(\d+) ?kva", n)
    if "main 132" in n: b = 9000
    elif m: b = float(m.group(1)) * 600
    elif "2mv" in n: b = 1200
    elif k: b = int(k.group(1)) * .6
    elif "compressor" in n: b = 560
    elif re.search(r"winder|skip|cage", n): b = 650
    elif re.search(r"mill|crus", n): b = 800
    elif "vfd" in n: b = 260
    elif re.search(r"fan|motor", n): b = 170
    elif re.search(r"mine|gantry|portal|adit|mrl|mrc|level|incline|trafo|\btr\b|transformer", n): b = 420
    elif re.search(r"colony|guest|football|workshop", n): b = 70
    elif re.search(r"i/c|incomer|main|grid|coupler|bus", n): b = 1500
    else: b = 140
    return b * (.75 + .5 * r.random())

class Meter:
    def __init__(self, loc, sr, name, make, rs):
        self.loc, self.sr, self.name, self.make, self.rs = loc, sr, name, make, rs
        self.nometer = False  # Populates all 230 meters with live telemetry & modal data
        r = random.Random(sr * 7919); n = name.lower()
        self.kv = kv_of(name); self.nom = self.kv * 1000
        self.base = base_of(name, r); self.cap = "capacitor" in n; self.spare = "spare" in n
        self.dg = bool(re.search(r"\bdg\b|dg-|dg i|dg a", n)); self.dead = False
        self.x = 0.0; self.ph = r.random() * 6.28; self.per = 50 + r.random() * 80
        self.imb = [r.random() * .02 - .01 for _ in range(3)]
        self.pf = (.86 if r.random() < .1 else .95) + r.random() * .04
        self.thdi = 3 + r.random() * 5; self.thdv = 1 + r.random() * 1.8
        # Seed initial realistic alarms on specific feeders so Alarm button & board are active immediately
        self.ex = (time.time() + 3600, "pf") if sr in (9, 21, 55, 89, 159) else ((time.time() + 3600, "thd") if sr in (65, 140, 204) else None)
        if sr == 1: self.pf = .975
        if self.cap: self.base *= .9; self.pf = .92
        if self.spare: self.base = 12.5
        self.rated = self.base * 1.6
        self.idleprone = bool(MOTORRE.search(name)) and sr % 7 == 0 and not (self.dg or self.cap or self.spare)
        hrs = max(1.0, datetime.datetime.now().hour + datetime.datetime.now().minute / 60)
        self.kwh0 = 1e5 + r.random() * 8e6; self.td = self.base * .9 * hrs; self.tc = self.td * 6.6
        self.last = time.time() - 1.0; self.v = None; self.status = "SIM"
        self.real_ts = 0; self.real_v = None; self.ever_real = False; self.cfg = None; self.base_kwh = None
        self.sim_step(time.time())  # Immediately populate self.v so no parameter is ever blank
    def sim_step(self, now):
        dt = min(5.0, now - self.last) or 1.0; self.last = now; nom = self.nom; g = random.gauss
        if self.dead:
            z = [0.0] * 3
            self.v = dict(vll=z, vln=z, i=z, p=z, q=z, s=z, pf=z, thdv=z, thdi=z, f=0.0, pft=0.0,
                          tot=dict(p=0.0, q=0.0, s=0.0), avg=dict(vll=0.0, vln=0.0, i=0.0), e=dict(kwh=self.kwh0)); return
        self.x += -.04 * self.x + g(0, .012)
        if not self.ex and random.random() < .00012: self.ex = (now + 90 if False else now + 25, random.choice(["sag", "pf", "thd", "swell", "surge"]))
        if self.ex and now > self.ex[0]: self.ex = None
        k = self.ex[1] if self.ex else None
        wave = 1 + .07 * math.sin(now / self.per * 6.28 + self.ph)
        P = .2 * (1 + g(0, .1)) if self.spare else self.base * max(.05, (1 + self.x) * wave)
        if k == "surge": P *= 1.8
        if self.idleprone and ((now / 60 + self.sr * 3.7) % 40) < 12: P *= .12     # demo: periodic no-load running
        vf = 1 + g(0, .0025) + (-.12 if k == "sag" else .11 if k == "swell" else 0)
        pf = .02 if self.cap else min(.995, max(.3, self.pf + g(0, .004) - (.18 if k == "pf" else 0)))
        vln = [nom / 1.732 * vf * (1 + self.imb[j] + g(0, .001)) for j in range(3)]
        vll = [x * 1.732 * (1 + g(0, .0008)) for x in vln]
        S = self.base * .6 if self.cap else P / pf
        Q = -S if self.cap else math.sqrt(max(0, S * S - P * P))
        p = [P / 3 * (1 + self.imb[j] * 3) for j in range(3)]; sp = [S / 3 * (1 + self.imb[j] * 3) for j in range(3)]
        i = [sp[j] * 1000 / vln[j] for j in range(3)]
        thdv = [self.thdv + g(0, .12) + (5 if k == "thd" else 0) for _ in range(3)]
        thdi = [(6 if self.sr in (76, 77) else self.thdi) + g(0, .4) + (9 if k == "thd" else 0) for _ in range(3)]
        self.kwh0 += P * dt / 3600; self.td += P * dt / 3600; self.tc += P * dt / 3600 * rate_now()[3]
        self.v = dict(vll=vll, vln=vln, i=i, p=p, q=[Q / 3] * 3, s=sp, pf=[pf] * 3, thdv=thdv, thdi=thdi, f=50 + g(0, .03), pft=pf,
                      tot=dict(p=P, q=Q, s=S), avg=dict(vll=sum(vll) / 3, vln=sum(vln) / 3, i=sum(i) / 3), e=dict(kwh=self.kwh0))

def rate_now():
    d = datetime.datetime.now(); h = d.hour + d.minute / 60
    tod = CFG["settings"]["tod"] if CFG else TOD_DEFAULT
    return next((t for t in tod if t[0] <= h < t[1]), tod[0])

METERS = [Meter(*m) for m in METERS_RAW]
