# ------------------------------------------------------------------ Modbus TCP (read-only, function 3 / 4)
def _recvn(s, n):
    b = b""
    while len(b) < n:
        c = s.recv(n - len(b))
        if not c: raise ConnectionError("closed")
        b += c
    return b

def mb_read(s, tid, unit, addr, qty, fc=3):
    s.sendall(struct.pack(">HHHBBHH", tid & 0xFFFF, 0, 6, unit, fc, addr, qty))
    h = _recvn(s, 7); ln = struct.unpack(">H", h[4:6])[0]; body = _recvn(s, ln - 1)
    if body[0] & 0x80: raise IOError("modbus exception %d" % body[1])
    if body[1] != qty * 2: raise IOError("short reply")
    return struct.unpack(">%dH" % qty, body[2:2 + qty * 2])

def f32(r, i):
    v = struct.unpack(">f", struct.pack(">HH", r[i], r[i + 1]))[0]
    return v if math.isfinite(v) else None

def parse_pac3200(main, pft, kwh, cfg):
    t3 = lambda o: [f32(main, o + 2 * k) for k in range(3)]
    vln, vll, cur, s, p, q, pf, thdv, thdi = (t3(o) for o in (0, 6, 12, 18, 24, 30, 36, 42, 48))
    if None in vll: raise ValueError("bad frame")
    kw = lambda a: [(x or 0) / 1000 for x in a]
    P, Q, S = kw(p), kw(q), kw(s)
    return dict(vll=vll, vln=vln, i=cur, p=P, q=Q, s=S, pf=pf, thdv=thdv, thdi=thdi, f=f32(main, 54), pft=pft,
                tot=dict(p=sum(P), q=sum(Q), s=sum(S)), avg=dict(vll=sum(vll) / 3, vln=sum(vln) / 3, i=sum(x or 0 for x in cur) / 3),
                e=dict(kwh=kwh))

# ------------------------------------------------------------------ state, tick, snapshot
STATE = {}
SNAP = [b'{"m":[]}']

def load_state():
    global STATE
    try: STATE = json.load(open(STATE_PATH))
    except Exception: STATE = {}

def tick_loop():
    last_save = 0
    while True:
        now = time.time(); today = datetime.date.today().isoformat(); out = []
        with LOCK:
            for m in METERS:
                if m.nometer: continue
                if m.ever_real:
                    if m.real_v and now - m.real_ts < 10:
                        m.status = "LIVE"; m.v = m.real_v
                        kw = m.v["e"]["kwh"]
                        st = STATE.get(str(m.sr))
                        if kw is not None and (not st or st["d"] != today): st = STATE[str(m.sr)] = {"d": today, "s": kw, "l": kw, "c": 0.0}
                        if st and kw is not None:
                            dl = kw - st["l"]
                            if 0 < dl < 5000: st["c"] += dl * rate_now()[3]; st["l"] = kw
                            m.td, m.tc = kw - st["s"], st["c"]
                    else: m.status = "OFFLINE"
                else:
                    m.sim_step(now); m.status = "STANDBY" if m.dead else "SIM"
                if m.status == "OFFLINE" and not getattr(m, "_off", False): m._off = True; audit("system", "Meter %s (%s) OFFLINE" % (m.sr, m.name))
                if m.status == "LIVE": m._off = False
                v = m.v; c = m.cfg
                nom = c["vll"] if (m.ever_real and c) else m.nom
                rated = c["prated"] * 3 if (m.ever_real and c) else m.rated
                out.append({"sr": m.sr, "st": m.status, "rl": 1 if m.ever_real else 0, "pt": 1 if (m.cfg and not m.ever_real) else 0, "nom": nom, "rated": round(rated, 2),
                            "td": round(m.td, 2), "tc": round(m.tc, 2), "v": v})
        dt = now - TICKST["t"]; TICKST["t"] = now
        with LOCK:
            try:
                md_tick(now, dt); plant_tick(now, dt)
                if now - TICKST["an"] >= 5: TICKST["an"] = now; analyze(now)
                if now - TICKST["pl"] >= 2: TICKST["pl"] = now; PSNAP[0] = json.dumps(plant_snapshot(now), separators=(",", ":")).encode()
            except Exception as e: print("plant tick error:", repr(e))
        def rd(o):
            if isinstance(o, float): return round(o, 3)
            if isinstance(o, list): return [rd(x) for x in o]
            if isinstance(o, dict): return {k: rd(x) for k, x in o.items()}
            return o
        SNAP[0] = json.dumps({"t": now, "m": rd(out)}, separators=(",", ":")).encode()
        if now - last_save > 60:
            last_save = now
            try: json.dump(STATE, open(STATE_PATH, "w"))
            except Exception: pass
        time.sleep(max(0.05, 1 - (time.time() - now)))

