def import_xlsx(path):
    import openpyxl
    wb = openpyxl.load_workbook(path, data_only=True); av = wb["Actual VS Target"]
    names = ["Mochia", "Balaria", "Zawarmala", "Baroi", "Mill-1", "Mill-2"]; num = lambda v: v if isinstance(v, (int, float)) else None
    cols = [(c.column, c.value.date().isoformat()) for c in av[7] if isinstance(c.value, datetime.datetime)]
    D = {}
    for col, d in cols:
        o = {}
        for k, nm in enumerate(names):
            r = 10 + k; kw, pr, bp = (num(av.cell(r, col + x).value) for x in (0, 1, 3))
            if kw and kw > 0: o[nm] = [round(kw), round(pr, 1) if pr else None, round(bp, 2) if bp else None]
        if o: D[d] = o
    dates = sorted(D); H = {"dates": dates, "A": {}, "F": {}}
    for a in names:
        H["A"][a] = {"k": [D[d].get(a, [None])[0] for d in dates], "p": [D[d].get(a, [0, None])[1] for d in dates], "b": [D[d].get(a, [0, 0, None])[2] for d in dates]}
    def feeders(sheet, namerow, cols_):
        ws = wb[sheet]; R = list(ws.iter_rows(min_row=1, values_only=True)); out = []
        for c in cols_:
            nm = R[namerow - 1][c]; op = str(R[3][c] or "").lower()
            if not nm or not any(x in op for x in ("add", "sub")): continue
            ser = {r[0].date().isoformat(): round(r[c]) for r in R[4:] if isinstance(r[0], datetime.datetime) and isinstance(r[c], (int, float))}
            out.append({"n": str(nm).strip(), "s": -1 if "sub" in op else 1, "d": [ser.get(d) for d in dates]})
        return [f for f in out if any(abs(x or 0) for x in f["d"])]
    def col(sheet, c):
        return {r[0].date().isoformat(): r[c] for r in wb[sheet].iter_rows(min_row=5, values_only=True) if isinstance(r[0], datetime.datetime) and isinstance(r[c], (int, float))}
    H["F"] = {"Mochia": feeders("Mochia", 2, range(10, 18)), "Balaria": feeders("Balaria", 3, range(10, 20)), "Mill-1": feeders("Mill", 3, range(10, 18)), "Mill-2": feeders("Mill", 3, range(22, 25))}
    for nm, c in (("North Baroi", 18), ("Central Baroi", 19)):
        s = col("Baroi ", c); H["F"].setdefault("Baroi", []).append({"n": nm, "s": 1, "d": [round(s[d]) if d in s else None for d in dates]})
    pf = col("Zawarmala", 10); pfd = [round(pf[d]) if d in pf else None for d in dates]; zk = H["A"]["Zawarmala"]["k"]
    H["F"]["Zawarmala"] = [{"n": "Paste fill plant", "s": 1, "d": pfd}, {"n": "Zawarmala plant (excl. paste fill)", "s": 1, "d": [(k - (p or 0)) if k is not None else None for k, p in zip(zk, pfd)]}]
    json.dump(H, open(HIST_PATH, "w"), separators=(",", ":"))
    print("History written to %s (%d days, last %s). Reload the page to see it." % (HIST_PATH, len(dates), dates[-1]))

# ================================================================== SMELTER PROCESS UNITS, ANALYTICS, KPIs
# Process tags come from the DCS/PI. Until a tag is pushed to /api/ingest it shows generated (SIM) values.
from email.message import EmailMessage

DB_PATH = os.path.join(HOME, "vidyut_data.db")
EVT_PATH = os.path.join(HOME, "vidyut_events.json")
PLANTS = ["ROASTER", "ACID", "SINTER", "ISF", "MC"]
PNAME = {"ROASTER": "Roaster", "ACID": "Acid plant", "SINTER": "Sinter plant", "ISF": "ISF plant", "MC": "Melting & casting"}
# id, name, group, rated kW, depends-on plant, rated flow
ASSETS = [("CAC1", "Centrifugal air compressor 1", "Compressed air", 660, None, 110.0), ("CAC2", "Centrifugal air compressor 2", "Compressed air", 660, None, 110.0),
          ("CAC3", "Screw compressor 3 (VFD)", "Compressed air", 160, None, 28.0), ("SO2B", "SO₂ blower", "Blowers", 3150, "ACID", 190000.0),
          ("RABB", "RAB blower", "Blowers", 1320, "ROASTER", 90000.0), ("RECT", "Electrowinning rectifier", "Rectifier", 100000, None, None),
          ("P101", "Intermediate pump P-101", "Pumps", 75, None, 200.0), ("P102", "Intermediate pump P-102", "Pumps", 75, None, 200.0),
          ("P103", "Intermediate pump P-103", "Pumps", 55, None, 150.0), ("P104", "Sinter cooling pump P-104", "Pumps", 55, "SINTER", 150.0)]
BURNERS = [("B1", "Roaster burner", "LDO"), ("B2", "Acid plant burner", "LDO"), ("B3", "Melting furnace 1", "LDO"), ("B4", "Melting furnace 2", "LDO")]
STOP_BURN = {"ROASTER": ("LDO", 150), "ACID": ("LDO", 110), "SINTER": ("LDO", 140), "ISF": ("COKE", 1200), "MC": ("PROPANE", 15)}  # kg/h held fuel - SAMPLE assumptions
ASSET = {a[0]: a for a in ASSETS}
TAGS = {}
PS = {"run": {p: [True, 0] for p in PLANTS}, "t0": time.time()}
HOURS = {}
INGEST_MAX = 400

def _tag(n, v=0.0):
    TAGS.setdefault(n, {"v": v, "src": "SIM", "rv": None, "rts": 0})
for a in ASSETS:
    for s in ("KW", "RUN", "FLOW"): _tag(a[0] + "_" + s)
for n in ("AIR_HDR", "AIR_SET", "AIR_USERMIN", "SO2_I", "SO2_PSUC", "SO2_PDIS", "RAB_I", "PROP_KGH", "COKE_TPH"): _tag(n)
for b in BURNERS:
    for s in ("FLOW", "OILP", "AIR", "O2"): _tag(b[0] + "_" + s)
for p in PLANTS: _tag("RUN_" + p, 1.0)

def plant_sim(now):
    g = random.gauss; t = now; S = PS
    for p in PLANTS:
        r = S["run"][p]
        if r[0] and random.random() < .0004: r[0], r[1] = False, now + random.uniform(40, 90)
        elif not r[0] and now > r[1]: r[0] = True
    run = {p: S["run"][p][0] for p in PLANTS}; sv = {}
    for p in PLANTS: sv["RUN_" + p] = 1.0 if run[p] else 0.0
    D = .62 + .12 * math.sin(t / 90) + g(0, .01)
    sv["CAC1_RUN"] = 1; sv["CAC1_KW"] = 660 * (.55 + .4 * D); sv["CAC1_FLOW"] = 110 * D
    sv["CAC2_RUN"] = 1; sv["CAC2_KW"] = 235 + g(0, 4); sv["CAC2_FLOW"] = 6 + g(0, .8)           # running unloaded (blow-off)
    sv["CAC3_RUN"] = 1; sv["CAC3_KW"] = 160 * (.4 + .5 * D); sv["CAC3_FLOW"] = 28 * D
    sv["AIR_SET"] = 7.4; sv["AIR_HDR"] = 7.4 + .12 * math.sin(t / 20) + g(0, .03); sv["AIR_USERMIN"] = 6.9 + g(0, .03)
    f = 1.09 + .02 * math.sin(t / 300) + g(0, .004); flow = 175000 * (1 + g(0, .01))
    dp = 380 * f; k = 1 if run["ACID"] else 0
    sv["SO2B_RUN"] = k; sv["SO2B_FLOW"] = flow * k; sv["SO2_PSUC"] = -60 * f; sv["SO2_PDIS"] = dp - 60 * f
    sv["SO2B_KW"] = k * 2650 * (flow / 175000) * f; sv["SO2_I"] = k * 275 * (flow / 175000) * f
    k = 1 if run["ROASTER"] else 0; sv["RABB_RUN"] = k; sv["RABB_FLOW"] = 82000 * k; sv["RABB_KW"] = 1120 * k * (1 + g(0, .01)); sv["RAB_I"] = 118 * k
    sv["RECT_RUN"] = 1; sv["RECT_KW"] = 95000 + 2500 * math.sin(t / 400) + g(0, 300); sv["RECT_FLOW"] = 0
    sv["P101_RUN"] = 1; sv["P101_FLOW"] = 190 + g(0, 3); sv["P101_KW"] = 66 + g(0, 1)
    sv["P102_RUN"] = 1; sv["P102_FLOW"] = 8 + g(0, 1); sv["P102_KW"] = 41 + g(0, 1)               # running on recirculation
    sv["P103_RUN"] = 0; sv["P103_FLOW"] = 0; sv["P103_KW"] = 0
    k = 1 if run["SINTER"] else 0; sv["P104_RUN"] = 1; sv["P104_FLOW"] = 120 * k; sv["P104_KW"] = 46 + g(0, 1)  # keeps running if sinter stops
    for b in BURNERS:
        if b[0] == "B1": base = 150 if not run["ROASTER"] else 18
        elif b[0] == "B2": base = 110 if not run["ACID"] else 14
        else: base = 112
        drift = min(.3, (t - S["t0"]) % 2400 / 2400 * .3) if b[0] == "B3" else 0.0     # demo: B3 nozzle slowly chokes, resets every 40 min
        idx = 1.0 + drift + g(0, .006); fl = base * (1 + g(0, .01))
        oilp = (9.0 / 112 ** 2) * idx * fl * fl * (1 + g(0, .004))                      # oil pressure = K x index x flow^2
        o2 = (3.1 if b[0] != "B4" else 5.6) + g(0, .12) + (.8 if b[0] == "B3" else 0)
        sv[b[0] + "_FLOW"] = fl; sv[b[0] + "_OILP"] = oilp; sv[b[0] + "_O2"] = o2; sv[b[0] + "_AIR"] = fl * 14.0 * (1 + o2 / (21 - o2))
    sv["PROP_KGH"] = 16.7 + g(0, .3); sv["COKE_TPH"] = (5.6 if run["ISF"] else 1.2) + g(0, .05)
    for n, v in sv.items():
        T = TAGS[n]
        if T["rv"] is not None and now - T["rts"] < 30: T["v"], T["src"] = T["rv"], "LIVE"
        else: T["v"], T["src"] = v, "SIM"

def tg(n): return TAGS[n]["v"]
def tsrc(names): return "LIVE" if all(TAGS[n]["src"] == "LIVE" for n in names) else "SIM" if all(TAGS[n]["src"] == "SIM" for n in names) else "MIXED"

# ---------------------------------------------------------------- events store (stoppages, actions, acks, baseline)
EVT = {"stops": [], "actions": {}, "acks": {}, "base": {}, "waste": [], "ideas": []}
def load_evt():
    global EVT
    try: EVT = json.load(open(EVT_PATH, encoding="utf-8"))
    except Exception: EVT = {"stops": [], "actions": {}, "acks": {}, "base": {}, "waste": [], "ideas": []}
    for k in ("stops", "actions", "acks", "base", "waste", "ideas"): EVT.setdefault(k, [] if k in ("stops", "waste", "ideas") else {})
    if not EVT["stops"]:
        r = random.Random(11); now = time.time()
        for i in range(10):
            p = r.choice(PLANTS); st = now - r.uniform(1, 29) * 86400; h = r.uniform(.6, 6)
            EVT["stops"].append({"id": "S%d" % (i + 1), "plant": p, "start": st, "end": st + h * 3600, "cause": r.choice(["Power dip", "Feed interruption", "Instrument air low", "Burner trip", "Planned-unplanned overrun"]), "src": "SAMPLE", "by": "-"})
        save_evt()

def save_evt():
    tmp = EVT_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f: json.dump(EVT, f)
    os.replace(tmp, EVT_PATH)

def stop_fuel(ev):
    fuel, rate = STOP_BURN[ev["plant"]]; h = ((ev.get("end") or time.time()) - ev["start"]) / 3600
    kg = h * rate; S = CFG["settings"]; price = {"LDO": S["p_ldo"], "PROPANE": S["p_prop"], "COKE": S["p_coke"]}[fuel]; ef = {"LDO": S["e_ldo"], "PROPANE": S["e_prop"], "COKE": S["e_coke"]}[fuel]
    return {"hours": round(h, 2), "fuel": fuel, "kg": round(kg), "cost": round(kg * price), "co2": round(kg * ef)}

PREV_RUN = {}
def track_stops(now):
    for p in PLANTS:
        r = tg("RUN_" + p) > .5; was = PREV_RUN.get(p, True); PREV_RUN[p] = r
        if was and not r:
            EVT["stops"].append({"id": "S%d" % (len(EVT["stops"]) + 1), "plant": p, "start": now, "end": None, "cause": "Auto-detected (run signal dropped)", "src": TAGS["RUN_" + p]["src"] + "-AUTO", "by": "system"})
            audit("system", "Unplanned stoppage detected: " + PNAME[p])
        elif r and not was:
            for e in reversed(EVT["stops"]):
                if e["plant"] == p and e["end"] is None: e["end"] = now; break
            save_evt()

# ---------------------------------------------------------------- analytics
FIND, AN, FLAT = {}, {}, {}
MOTORRE = re.compile(r"motor|compressor|pump|fan|winder|mill|crus|vfd|skip|cage", re.I)
def blended_rate():
    tod = CFG["settings"]["tod"] if CFG else TOD_DEFAULT; h = sum(t[1] - t[0] for t in tod)
    return sum((t[1] - t[0]) * t[3] for t in tod) / h if h else 0

def fnd(H, id, typ, asset, sev, title, ev, cause, action, kpi, kwh=None, fuel=None, conf="Medium", risk="Low", metric=None):
    S = CFG["settings"]; f = {"id": id, "type": typ, "asset": asset, "sev": sev, "title": title, "evidence": ev, "cause": cause, "action": action, "kpi": kpi, "conf": conf, "risk": risk, "metric": metric}
    if kwh is not None: f.update(kwh_day=round(kwh), cost_day=round(kwh * blended_rate()), co2_day=round(kwh * S["ef"]))
    if fuel:
        fl, kg = fuel; price = {"LDO": S["p_ldo"], "PROPANE": S["p_prop"], "COKE": S["p_coke"]}[fl]; ef = {"LDO": S["e_ldo"], "PROPANE": S["e_prop"], "COKE": S["e_coke"]}[fl]
        f.update(fuel=fl, fuel_kg_day=round(kg), cost_day=round(kg * price), co2_day=round(kg * ef))
    H[id] = f

def analyze(now):
    S = CFG["settings"]; H = {}
    # compressed air: header pressure setpoint
    sp, usr = tg("AIR_SET"), tg("AIR_USERMIN"); drop = tg("AIR_HDR") - usr; need = S["air_req"] + max(0, drop) + .3
    kw = sum(tg(c + "_KW") for c in ("CAC1", "CAC2", "CAC3"))
    if sp - need >= .07:
        step = .07; pct = .5 * step * 14.5
        fnd(H, "AIR_SETPT", "Compressed air pressure", "Air header", 1, "Header setpoint higher than process needs",
            "Setpoint %.2f bar; header %.2f bar; lowest user %.2f bar (requirement %.1f bar). Distribution drop %.2f bar. Supportable header ≈ %.2f bar." % (sp, tg("AIR_HDR"), usr, S["air_req"], drop, need),
            "Setpoint set with margin above real requirement", "Lower setpoint in steps of 0.07 bar (≈1 %%), watch lowest user pressure; final target ≈ %.2f bar. Operator approval needed; VFD compressor can trim." % need,
            "KPI 2", kwh=kw * 24 * pct / 100, conf="Medium (rule of thumb ≈0.5 %% power per psi - verify)", risk="Low if user pressure stays ≥ requirement", metric={"n": "Setpoint", "v": sp, "u": "bar"})
    for c in ("CAC1", "CAC2", "CAC3"):
        a = ASSET[c]; k, fl = tg(c + "_KW"), tg(c + "_FLOW")
        if tg(c + "_RUN") > .5 and k > .25 * a[3] and fl < .15 * a[5]:
            fnd(H, "IDLE_" + c, "Idle running", a[1], 2, "Compressor running unloaded", "%.0f kW drawn for %.1f of %.0f Nm³/min (%.0f %% load)." % (k, fl, a[5], fl / a[5] * 100),
                "Surplus compressor on blow-off / unloaded", "Stop or keep as standby if sequencing allows; confirm with operations that demand is covered.", "KPI 5", kwh=k * 24 * .9, conf="High", risk="Medium: check redundancy", metric={"n": "kW", "v": k, "u": "kW"})
    for pid in ("P101", "P102", "P103", "P104"):
        a = ASSET[pid]; k, fl, run = tg(pid + "_KW"), tg(pid + "_FLOW"), tg(pid + "_RUN") > .5
        dep = a[4] and tg("RUN_" + a[4]) < .5
        if run and (fl < .1 * a[5] or dep):
            why = "its plant (%s) is stopped" % PNAME[a[4]] if dep else "flow only %.0f of %.0f m³/h (recirculation)" % (fl, a[5])
            fnd(H, "IDLE_" + pid, "Idle running", a[1], 2, "Pump running without useful output", "%.0f kW drawn; %s." % (k, why), "No demand / recirculation / standby left running",
                "Stop or switch to standby where process permits; consider VFD or auto-stop interlock.", "KPI 5", kwh=k * 24 * .9, conf="High", risk="Low–Medium", metric={"n": "kW", "v": k, "u": "kW"})
    # SO2 blower pressure drop
    base = EVT["base"].setdefault("so2_dp", 380.0); dp = tg("SO2_PDIS") - tg("SO2_PSUC")
    if tg("SO2B_RUN") > .5 and dp > base * (1 + S["dp_warn"] / 100):
        exc = (dp - base) / dp; k = tg("SO2B_KW")
        fnd(H, "SO2_DP", "SO₂ blower pressure drop", "SO₂ blower", 2 if dp > base * 1.12 else 1, "System pressure drop above baseline",
            "ΔP %.0f mbar vs baseline %.0f mbar (+%.1f %%); blower %.0f kW, %.0f A." % (dp, base, (dp / base - 1) * 100, k, tg("SO2_I")),
            "Possible fouling/choking in scrubbing, demister, ducts or gas-cooling section", "Inspect differential pressures section by section (cooling tower, ESP, demister, mist filter, ducts), clean the section with the largest rise.",
            "KPI 3", kwh=k * 24 * exc * .8, conf="Low–Medium (power ∝ flow × ΔP)", risk="Low", metric={"n": "ΔP", "v": dp, "u": "mbar"})
    # burners
    for b, nm, fuel in BURNERS:
        fl, oilp, o2 = tg(b + "_FLOW"), tg(b + "_OILP"), tg(b + "_O2")
        if fl < 1: continue
        idx = oilp / (fl * fl) * 1.0; b0 = EVT["base"].setdefault("nz_" + b, idx); ri = idx / b0 if b0 else 1
        if ri > 1 + S["choke_warn"] / 100:
            fnd(H, "CHOKE_" + b, "Burner nozzle choking", nm, 2 if ri > 1 + S["choke_alarm"] / 100 else 1, "Nozzle resistance rising",
                "Nozzle index %.2f× clean baseline; oil pressure %.1f bar, flow %.0f kg/h." % (ri, oilp, fl), "Carbon/ash deposition or partial blockage of the nozzle or strainer",
                "Schedule nozzle and strainer cleaning at next safe opportunity; check atomising steam/air.", "KPI 6", conf="Medium", risk="Low", metric={"n": "Nozzle index", "v": ri, "u": "×"})
        if o2 > S["o2_hi"]:
            pct = (o2 - S["o2_hi"]) * .45; kg = fl * 24 * pct / 100
            fnd(H, "AF_" + b, "Air–fuel ratio", nm, 1, "Excess air above target band", "Flue O₂ %.1f %% (target %.1f–%.1f %%); excess air carries heat out of the stack." % (o2, S["o2_lo"], S["o2_hi"]),
                "Combustion air too high for the fuel rate", "Trim air damper / ratio within approved limits to bring O₂ into band. Never override flame-safety or BMS interlocks; operator approval required.", "KPI 7",
                fuel=("LDO", kg), conf="Low (≈0.45 %% fuel per 1 %% O₂ excess - verify)", risk="Medium: stay inside approved limits", metric={"n": "O₂", "v": o2, "u": "%"})
        elif o2 < S["o2_lo"]:
            fnd(H, "AF_" + b, "Air–fuel ratio", nm, 2, "Air deficit (O₂ below band)", "Flue O₂ %.1f %% below %.1f %%: incomplete combustion risk." % (o2, S["o2_lo"]), "Insufficient combustion air", "Check air damper, fan and nozzle; raise air within approved limits.", "KPI 7", conf="Medium", risk="High: safety", metric={"n": "O₂", "v": o2, "u": "%"})
    # repeat stoppages
    for p in PLANTS:
        ev = [e for e in EVT["stops"] if e["plant"] == p and e["start"] > now - 30 * 86400]
        if len(ev) >= 3:
            kg = sum(stop_fuel(e)["kg"] for e in ev); fuel = STOP_BURN[p][0]
            fnd(H, "STOP_" + p, "Repeated stoppages", PNAME[p], 1, "Recurring unplanned stoppages", "%d stoppages in 30 days, %.1f h total; ≈ %s kg %s held while stopped." % (len(ev), sum(stop_fuel(e)["hours"] for e in ev), format(kg, ","), fuel),
                "Recurring trips / feed or utility interruptions", "Run root-cause review on the top causes; fix the most frequent first.", "KPI 4", fuel=(fuel, kg / 30), conf="Medium", risk="Low", metric={"n": "Stoppages/30 d", "v": len(ev), "u": ""})
    # motor installation / health (meters)
    for m in METERS:
        if m.nometer or not m.v or m.status == "OFFLINE" or not MOTORRE.search(m.name): continue
        v = m.v
        if v["avg"]["vll"] < .5 * m.nom or v["tot"]["p"] < .2 * m.rated: continue
        i = v["i"]; ia = sum(i) / 3; cu = max(abs(x - ia) for x in i) / ia * 100 if ia else 0; vl = v["vll"]; va = sum(vl) / 3; vu = max(abs(x - va) for x in vl) / va * 100
        if cu > 10 or vu > 2:
            fnd(H, "MOT_%d" % m.sr, "Motor installation / supply", m.name + " (" + m.loc[:20] + ")", 2 if cu > 15 else 1, "Phase imbalance on motor feeder", "Current unbalance %.1f %% (limit 10 %%), voltage unbalance %.1f %% (limit 2 %%)." % (cu, vu),
                "Loose/high-resistance termination, uneven supply, or winding fault", "Check terminations and supply balance; thermal-scan connections; confirm IE3 motor is correctly installed and aligned.", "Outputs: motor failures", conf="Medium", risk="Low", metric={"n": "I unbalance", "v": cu, "u": "%"})
    md_finding(H, now); meter_findings(H, now)
    for id, f in H.items():
        o = FIND.get(id)
        if o: o.update(f); o["hits"] = min(o["hits"] + 1, 10); o["miss"] = 0
        else: FIND[id] = dict(f, hits=1, miss=0, first=now)
    for id in list(FIND):
        if id not in H:
            FIND[id]["miss"] += 1
            if FIND[id]["miss"] >= 3: FIND[id]["hits"] = 0
    for id, f in FIND.items():
        if f["hits"] >= 3 and id not in EVT["actions"]:
            EVT["actions"][id] = {"status": "Pending", "first": now}; save_evt()
            if f["sev"] >= 2: notify("VIDYUT: %s - %s" % (f["asset"], f["title"]), f["evidence"] + "\n\nSuggested action: " + f["action"])
    # anomalies (EWMA baseline per series)
    series = [("A" + a[0], a[1], tg(a[0] + "_KW"), tg(a[0] + "_RUN") > .5) for a in ASSETS] + [("M%d" % m.sr, m.name, m.v["tot"]["p"], True) for m in METERS if not m.nometer and m.v and m.status != "OFFLINE" and not m.dead and m.v["tot"]["p"] > 5]
    for sid, nm, x, on in series:
        if not on: continue
        s = AN.get(sid)
        if not s: AN[sid] = {"m": x, "v": (.03 * abs(x) + .5) ** 2, "run": 0, "z": 0, "x": x, "name": nm}; continue
        sd = max(math.sqrt(s["v"]), .04 * abs(s["m"]) + .5); z = (x - s["m"]) / sd; s["z"], s["x"] = z, x
        if abs(z) > 4: s["run"] += 1
        else:
            s["run"] = 0; a = .05; d = x - s["m"]; s["m"] += a * d; s["v"] = (1 - a) * (s["v"] + a * d * d)
    # data quality on real meters
    for m in METERS:
        if m.ever_real and m.v:
            k = m.v["tot"]["p"]; f = FLAT.setdefault(m.sr, [k, 0])
            f[1] = f[1] + 1 if abs(k - f[0]) < 1e-9 else 0; f[0] = k

def anomalies():
    out = [dict(id=k, name=s["name"], now=round(s["x"], 1), base=round(s["m"], 1), z=round(s["z"], 1), dur=s["run"] * 5) for k, s in AN.items() if s["run"] >= 3]
    return sorted(out, key=lambda a: -abs(a["z"]))[:25]

def dq():
    cnt = {"LIVE": 0, "SIM": 0, "STANDBY": 0, "OFFLINE": 0, "NO METER": 0}
    for m in METERS: cnt["NO METER" if m.nometer else m.status] = cnt.get("NO METER" if m.nometer else m.status, 0) + 1
    flat = [{"sr": m.sr, "name": m.name} for m in METERS if m.ever_real and FLAT.get(m.sr, [0, 0])[1] > 30]
    off = [{"sr": m.sr, "name": m.name, "loc": m.loc} for m in METERS if m.status == "OFFLINE"]
    tl = sum(1 for t in TAGS.values() if t["src"] == "LIVE")
    return {"meters": cnt, "flat": flat, "offline": off, "tags_live": tl, "tags_total": len(TAGS), "coverage": round(100 * cnt["LIVE"] / max(1, sum(v for k, v in cnt.items() if k != "NO METER")), 1)}

def notify(subj, body):
    c = CFG.get("smtp") or {}
    if not c.get("enabled") or not c.get("to"): return
    def go():
        try:
            m = EmailMessage(); m["Subject"] = subj; m["From"] = c["from"]; m["To"] = ", ".join(c["to"]); m.set_content(body)
            with smtplib.SMTP(c["host"], int(c.get("port", 587)), timeout=15) as s:
                s.starttls()
                if c.get("user"): s.login(c["user"], c["pass"])
                s.send_message(m)
        except Exception as e: audit("system", "email failed: %s" % e)
    threading.Thread(target=go, daemon=True).start()

# ---------------------------------------------------------------- KPIs, fuel, snapshot
_HC = [0, None]
def hist():
    if time.time() - _HC[0] > 300 or _HC[1] is None: _HC[1] = json.loads(history_text()); _HC[0] = time.time()
    return _HC[1]

def energy_kpi():
    try:
        H = hist(); n = len(H["dates"]); a = n - 30; b = n - 120; num = den = 0
        for k, A in H["A"].items():
            kw, mt = A["k"], A["p"]
            cur_e = sum(x or 0 for x in kw[a:]); cur_m = sum(x or 0 for x in mt[a:]); bas_e = sum(x or 0 for x in kw[b:a]); bas_m = sum(x or 0 for x in mt[b:a])
            if cur_m and bas_m and bas_e: num += cur_e * (cur_e / cur_m) / (bas_e / bas_m) - cur_e; den += cur_e
        return num / den * 100 if den else None
    except Exception: return None

def fuel_state():
    S = CFG["settings"]; st = STATE.setdefault("fuel", {}); today = datetime.date.today().isoformat()
    if st.get("d") != today: st.clear(); st.update({"d": today, "ldo": 0.0, "prop": 0.0, "coke": 0.0, "kwh": 0.0})
    return st

def kpis(now):
    S = CFG["settings"]; K = []; B = EVT["base"]; sp = tg("AIR_SET")
    e = energy_kpi(); K.append({"id": "K1", "name": "Electrical energy consumption", "target": "−2 % specific energy", "value": "n/a" if e is None else "%+.1f %%" % e, "progress": None if e is None else max(0, min(100, -e / 2 * 100)), "st": 4 if e is None else 0 if e <= -2 else 1 if e < 0 else 2, "note": "Last 30 days vs previous 90 days, kWh/MT weighted by energy (workbook data)."})
    b = B.setdefault("air_set", sp); r = (b - sp) / b * 100 if b else 0; need = S["air_req"] + max(0, tg("AIR_HDR") - tg("AIR_USERMIN")) + .3
    K.append({"id": "K2", "name": "Compressor pressure setpoint", "target": "−1 % setpoint", "value": "%.2f %% lower (now %.2f bar)" % (r, sp), "progress": max(0, min(100, r)), "st": 0 if r >= 1 else 1 if r > 0 else 2, "note": "Baseline %.2f bar. Supportable setpoint ≈ %.2f bar." % (b, need)})
    dp = tg("SO2_PDIS") - tg("SO2_PSUC"); i = tg("SO2_I"); fl = max(tg("SO2B_FLOW"), 1); ni = i / fl * 1e5; run3 = tg("SO2B_RUN") > .5 and i > 0; bi = B.setdefault("so2_i", ni) if run3 else B.get("so2_i"); ch = (ni - bi) / bi * 100 if (bi and run3) else 0
    K.append({"id": "K3", "name": "SO₂ blower current", "target": "Reduce via pressure-drop fixes", "value": ("%+.1f %% (A per flow)" % ch) if run3 else "SO₂ blower stopped", "progress": max(0, min(100, -ch / 3 * 100)), "st": 0 if ch <= -1 else 1 if ch <= 1 else 2, "note": "System ΔP %.0f mbar vs baseline %.0f mbar." % (dp, B.get("so2_dp", 380))})
    c30 = sum(1 for x in EVT["stops"] if x["start"] > now - 30 * 86400); p30 = sum(1 for x in EVT["stops"] if now - 60 * 86400 < x["start"] <= now - 30 * 86400)
    K.append({"id": "K4", "name": "Unplanned stoppages (roaster, M&C, sinter, ISF)", "target": "Fewer than previous 30 days", "value": "%d vs %d" % (c30, p30), "progress": None if not p30 else max(0, min(100, (p30 - c30) / p30 * 100)), "st": 4 if not p30 else 0 if c30 < p30 else 1 if c30 == p30 else 2, "note": "Events logged automatically from run signals plus manual entries."})
    idle = sum(f.get("kwh_day", 0) for f in FIND.values() if f["hits"] >= 3 and f["type"] == "Idle running"); bi = B.setdefault("idle", idle)
    K.append({"id": "K5", "name": "Idle-running equipment", "target": "Minimise", "value": "%s kWh/day" % format(round(idle), ","), "progress": None if not bi else max(0, min(100, (bi - idle) / bi * 100)), "st": 0 if idle == 0 else 1 if idle <= bi else 2, "note": "%d items running without useful output." % sum(1 for f in FIND.values() if f["hits"] >= 3 and f["type"] == "Idle running")})
    ch = [f for f in FIND.values() if f["hits"] >= 3 and f["type"] == "Burner nozzle choking"]
    K.append({"id": "K6", "name": "Burner nozzle choking (AI detection)", "target": "Detect early, clean on time", "value": "%d active" % len(ch), "progress": 100 if not ch else 40, "st": 0 if not ch else max(f["sev"] for f in ch), "note": "Nozzle index = oil pressure ÷ flow², compared with each burner's clean baseline."})
    inb = [b for b in BURNERS if S["o2_lo"] <= tg(b[0] + "_O2") <= S["o2_hi"]]
    K.append({"id": "K7", "name": "Air–fuel ratio (LDO combustion)", "target": "Flue O₂ in band %.1f–%.1f %%" % (S["o2_lo"], S["o2_hi"]), "value": "%d of %d burners in band" % (len(inb), len(BURNERS)), "progress": len(inb) / len(BURNERS) * 100, "st": 0 if len(inb) == len(BURNERS) else 1 if len(inb) >= len(BURNERS) - 1 else 2, "note": "Recommendations only; no automatic control of burners."})
    return K

def seis(K, idle_kwh, pk, dqv):
    """Illustrative Site Energy Intelligence Score (weights 25/20/20/20/15) - a management indicator, not a standard."""
    g = {k["id"]: k["progress"] for k in K}; n = lambda v: 50.0 if v is None else v
    parts = [("Specific energy (K1)", 25, n(g.get("K1"))), ("Idle & waste (K5)", 20, max(0.0, 100 - idle_kwh / max(pk * 24, 1) * 100 * 20)),
             ("Stoppages (K4)", 20, n(g.get("K4"))), ("Combustion (K6/K7)", 20, (n(g.get("K6")) + n(g.get("K7"))) / 2), ("Data coverage", 15, dqv["coverage"])]
    return {"score": round(sum(w * v for _, w, v in parts) / 100, 1), "parts": [{"n": a, "w": w, "v": round(v, 1)} for a, w, v in parts], "note": "Illustrative weights - agree them with the energy committee before using as a target."}

def plant_snapshot(now):
    S = CFG["settings"]; fs = fuel_state(); ass = []
    for a in ASSETS:
        k = tg(a[0] + "_KW"); run = tg(a[0] + "_RUN") > .5; ids = [f["id"] for f in FIND.values() if f["hits"] >= 3 and f["id"].endswith(a[0])]
        ass.append({"id": a[0], "name": a[1], "group": a[2], "rated": a[3], "kw": round(k, 1), "run": run, "load": round(k / a[3] * 100, 1), "flow": round(tg(a[0] + "_FLOW"), 1), "rflow": a[5], "src": tsrc([a[0] + "_KW"]), "hours": round(HOURS.get(a[0], 0), 1), "finds": len(ids)})
    air = {"set": tg("AIR_SET"), "hdr": tg("AIR_HDR"), "usr": tg("AIR_USERMIN"), "req": S["air_req"], "need": S["air_req"] + max(0, tg("AIR_HDR") - tg("AIR_USERMIN")) + .3, "kw": sum(tg(c + "_KW") for c in ("CAC1", "CAC2", "CAC3")), "flow": sum(tg(c + "_FLOW") for c in ("CAC1", "CAC2", "CAC3")), "base": EVT["base"].get("air_set"), "src": tsrc(["AIR_HDR", "AIR_SET"])}
    dp = tg("SO2_PDIS") - tg("SO2_PSUC"); so2 = {"i": tg("SO2_I"), "kw": tg("SO2B_KW"), "flow": tg("SO2B_FLOW"), "dp": dp, "base": EVT["base"].get("so2_dp", 380), "psuc": tg("SO2_PSUC"), "pdis": tg("SO2_PDIS"), "run": tg("SO2B_RUN") > .5, "src": tsrc(["SO2_I", "SO2_PDIS"])}
    bur = []
    for b, nm, fuel in BURNERS:
        fl, oilp = tg(b + "_FLOW"), tg(b + "_OILP"); idx = oilp / (fl * fl) if fl > 1 else None; b0 = EVT["base"].get("nz_" + b)
        bur.append({"id": b, "name": nm, "fuel": fuel, "flow": fl, "oilp": oilp, "air": tg(b + "_AIR"), "o2": tg(b + "_O2"), "ratio": tg(b + "_AIR") / fl if fl > 1 else None, "idx": (idx / b0) if idx and b0 else None, "src": tsrc([b + "_FLOW", b + "_O2"])})
    pk = sum(tg(a[0] + "_KW") for a in ASSETS)
    fuel = {"ldo_kgh": sum(tg(b[0] + "_FLOW") for b in BURNERS), "prop_kgh": tg("PROP_KGH"), "coke_tph": tg("COKE_TPH"), "ldo": fs["ldo"], "prop": fs["prop"], "coke": fs["coke"], "kwh": fs["kwh"],
            "cost": fs["ldo"] * S["p_ldo"] + fs["prop"] * S["p_prop"] + fs["coke"] * 1000 * S["p_coke"], "s1": fs["ldo"] * S["e_ldo"] + fs["prop"] * S["e_prop"] + fs["coke"] * 1000 * S["e_coke"], "s2": fs["kwh"] * S["ef"], "src": tsrc(["PROP_KGH", "COKE_TPH"])}
    fl = []
    for f in FIND.values():
        if f["hits"] >= 3:
            a = EVT["actions"].get(f["id"], {}); fl.append(dict(f, status=a.get("status", "Pending"), by=a.get("by"), reason=a.get("reason"), at=a.get("at"), ack=EVT["acks"].get(f["id"]), base_metric=a.get("base_metric")))
    for id, a in EVT["actions"].items():
        if id not in FIND or FIND[id]["hits"] < 3:
            if a["status"] in ("Approved", "Implemented"): fl.append({"id": id, "type": "Resolved", "asset": id, "sev": 0, "title": "Condition cleared after approval", "evidence": "", "cause": "", "action": "", "kpi": "", "status": "Verified?", "by": a.get("by"), "reason": a.get("reason"), "at": a.get("at"), "base_metric": a.get("base_metric"), "metric": None})
    fl.sort(key=lambda f: (-f["sev"], f["id"]))
    stops = []
    for e in sorted(EVT["stops"], key=lambda e: -e["start"])[:60]: stops.append(dict(e, **stop_fuel(e)))
    by = {}
    for e in EVT["stops"]:
        if e["start"] > now - 30 * 86400:
            f = stop_fuel(e); d = by.setdefault(e["plant"], {"n": 0, "h": 0, "kg": 0, "cost": 0, "co2": 0, "fuel": f["fuel"]}); d["n"] += 1; d["h"] += f["hours"]; d["kg"] += f["kg"]; d["cost"] += f["cost"]; d["co2"] += f["co2"]
    pot = sum(f.get("kwh_day", 0) for f in fl if f.get("status") in ("Pending", "Approved", "Implemented")); appr = sum(f.get("kwh_day", 0) for f in fl if f.get("status") in ("Approved", "Implemented"))
    K = kpis(now); idle_kwh = sum(f.get("kwh_day", 0) for f in FIND.values() if f["hits"] >= 3 and f["type"] == "Idle running"); D = dq()
    return {"seis": seis(K, idle_kwh, pk, D), "t": now, "tags": {k: [round(v["v"], 3), v["src"]] for k, v in TAGS.items()}, "assets": ass, "air": air, "so2": so2, "burners": bur, "fuel": fuel, "finds": fl, "anoms": anomalies(), "dq": D, "kpi": K,
            "stops": stops, "stopsum": by, "stopburn": STOP_BURN, "proc_kw": pk, "pot_kwh_day": pot, "appr_kwh_day": appr, "proc_kwh_day": pk * 24, "pnames": PNAME, "md": md_view(), "waste_open": sum(1 for w in EVT["waste"] if w["state"] not in ("Closed", "Verified")), "tod": STATE.get("tod"), "ideas_n": len(EVT["ideas"])}

# ---------------------------------------------------------------- storage (SQLite, 1-minute averages)
DB = None
ACC = {}
def db_init():
    global DB
    DB = sqlite3.connect(DB_PATH, check_same_thread=False); DB.execute("CREATE TABLE IF NOT EXISTS reading(ts INTEGER, id TEXT, kw REAL)"); DB.execute("CREATE INDEX IF NOT EXISTS ix ON reading(id, ts)"); DB.commit()

def db_acc(now):
    for m in METERS:
        if not m.nometer and m.v and m.status != "OFFLINE": a = ACC.setdefault("M%d" % m.sr, [0.0, 0]); a[0] += m.v["tot"]["p"]; a[1] += 1
    for a_ in ASSETS: a = ACC.setdefault("A" + a_[0], [0.0, 0]); a[0] += tg(a_[0] + "_KW"); a[1] += 1
    ts = int(now // 60) * 60
    if ACC.get("_ts") is None: ACC["_ts"] = ts
    if ts > ACC["_ts"]:
        rows = [(ACC["_ts"], k, v[0] / v[1]) for k, v in ACC.items() if k != "_ts" and v[1]]
        try:
            DB.executemany("INSERT INTO reading VALUES (?,?,?)", rows)
            if int(now) % 86400 < 90: DB.execute("DELETE FROM reading WHERE ts<?", (now - 400 * 86400,))
            DB.commit()
        except Exception: pass
        ACC.clear(); ACC["_ts"] = ts

def db_profile(sid, hours):
    with LOCK:
        cur = DB.execute("SELECT (ts/3600)*3600 h, AVG(kw), COUNT(*) FROM reading WHERE id=? AND ts>? GROUP BY h ORDER BY h", (sid, time.time() - hours * 3600))
        return [[r[0], round(r[1], 2), r[2]] for r in cur.fetchall()]

def plant_tick(now, dt):
    dt = min(dt, 10.0)
    plant_sim(now); track_stops(now); fs = fuel_state()
    for a in ASSETS:
        if tg(a[0] + "_RUN") > .5: HOURS[a[0]] = HOURS.get(a[0], 0) + dt / 3600
    fs["ldo"] += sum(tg(b[0] + "_FLOW") for b in BURNERS) * dt / 3600; fs["prop"] += tg("PROP_KGH") * dt / 3600; fs["coke"] += tg("COKE_TPH") * dt / 3600
    fs["kwh"] += sum(tg(a[0] + "_KW") for a in ASSETS) * dt / 3600; db_acc(now)

# ---------------------------------------------------------------- forecast
def forecast():
    H = hist(); D = H["dates"]; out = {}
    names = dict(H["A"]); tot = [sum((A["k"][i] or 0) for A in H["A"].values()) for i in range(len(D))]; names["Plant total"] = {"k": tot}
    for nm, A in names.items():
        s = [x or 0 for x in A["k"]]
        def pred(i):
            same = [s[j] for j in (i - 7, i - 14, i - 21, i - 28) if j >= 0 and s[j]]; last = [x for x in s[max(0, i - 7):i] if x]
            if not same or not last: return None
            return .5 * sum(same) / len(same) + .5 * sum(last) / len(last)
        ape = []
        for i in range(len(s) - 28, len(s)):
            p = pred(i)
            if p and s[i]: ape.append(abs(p - s[i]) / s[i])
        fc = []; ext = s[:]
        for k in range(7):
            i = len(ext); same = [ext[j] for j in (i - 7, i - 14, i - 21, i - 28) if ext[j]]; last = [x for x in ext[i - 7:i] if x]
            v = .5 * sum(same) / len(same) + .5 * sum(last) / len(last); ext.append(v); fc.append(round(v))
        d0 = datetime.date.fromisoformat(D[-1]); out[nm] = {"dates": D[-28:], "actual": s[-28:], "fdates": [(d0 + datetime.timedelta(days=k + 1)).isoformat() for k in range(7)], "forecast": fc, "mape": round(sum(ape) / len(ape) * 100, 1) if ape else None}
    return out

# ---------------------------------------------------------------- Excel report (minimal .xlsx writer, standard library only)
def xlsx_bytes(sheets):
    from xml.sax.saxutils import escape
    def cn(i):
        s = ""; i += 1
        while i: i, r = divmod(i - 1, 26); s = chr(65 + r) + s
        return s
    bio = io.BytesIO(); z = zipfile.ZipFile(bio, "w", zipfile.ZIP_DEFLATED)
    z.writestr("[Content_Types].xml", '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' + "".join('<Override PartName="/xl/worksheets/sheet%d.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' % (i + 1) for i in range(len(sheets))) + "</Types>")
    z.writestr("_rels/.rels", '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
    z.writestr("xl/workbook.xml", '<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>' + "".join('<sheet name="%s" sheetId="%d" r:id="rId%d"/>' % (escape(n[:31]), i + 1, i + 1) for i, (n, _) in enumerate(sheets)) + "</sheets></workbook>")
    z.writestr("xl/_rels/workbook.xml.rels", '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' + "".join('<Relationship Id="rId%d" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet%d.xml"/>' % (i + 1, i + 1) for i in range(len(sheets))) + "</Relationships>")
    for i, (_, rows) in enumerate(sheets):
        x = ['<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>']
        for r, row in enumerate(rows):
            x.append('<row r="%d">' % (r + 1))
            for c, v in enumerate(row):
                ref = "%s%d" % (cn(c), r + 1)
                if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v): x.append('<c r="%s"><v>%s</v></c>' % (ref, repr(v)))
                elif v is not None: x.append('<c r="%s" t="inlineStr"><is><t>%s</t></is></c>' % (ref, escape(str(v))))
            x.append("</row>")
        x.append("</sheetData></worksheet>"); z.writestr("xl/worksheets/sheet%d.xml" % (i + 1), "".join(x))
    z.close(); return bio.getvalue()

def report_xlsx(kind):
    now = time.time(); P = plant_snapshot(now); S = CFG["settings"]; sh = []; ts = lambda t: datetime.datetime.fromtimestamp(t).strftime("%Y-%m-%d %H:%M") if t else ""
    if kind in ("all", "energy"):
        H = hist(); D = H["dates"]; rows = [["Date"] + [a + " kWh" for a in H["A"]] + ["Total kWh"]]
        for i in range(len(D) - 1, max(-1, len(D) - 91), -1): v = [H["A"][a]["k"][i] for a in H["A"]]; rows.append([D[i]] + v + [sum(x or 0 for x in v)])
        sh.append(("Daily energy (90 d)", rows))
        rows = [["Area", "kWh (30 d)", "MT (30 d)", "kWh/MT", "Budget kWh/MT"]]
        for a, A in H["A"].items():
            k = sum(x or 0 for x in A["k"][-30:]); m = sum(x or 0 for x in A["p"][-30:]); b = [x for x in A["b"][-30:] if x]
            rows.append([a, k, m, round(k / m, 2) if m else None, round(sum(b) / len(b), 2) if b else None])
        sh.append(("Specific energy", rows))
    if kind in ("all", "kpi"): sh.append(("KPIs", [["KPI", "Target", "Value", "Note"]] + [[k["name"], k["target"], k["value"], k["note"]] for k in P["kpi"]]))
    if kind in ("all", "actions"):
        sh.append(("Recommendations", [["ID", "Asset", "Issue", "Evidence", "Cause", "Action", "kWh/day", "Fuel", "kg/day", "Cost/day", "CO2 kg/day", "Confidence", "Risk", "Status", "Decided by", "Reason"]] + [[f["id"], f["asset"], f["title"], f.get("evidence"), f.get("cause"), f.get("action"), f.get("kwh_day"), f.get("fuel"), f.get("fuel_kg_day"), f.get("cost_day"), f.get("co2_day"), f.get("conf"), f.get("risk"), f.get("status"), f.get("by"), f.get("reason")] for f in P["finds"]]))
    if kind in ("all", "stoppages"): sh.append(("Stoppages", [["ID", "Plant", "Start", "End", "Hours", "Cause", "Source", "Fuel", "Held fuel kg", "Cost", "CO2 kg"]] + [[e["id"], PNAME[e["plant"]], ts(e["start"]), ts(e["end"]), e["hours"], e["cause"], e["src"], e["fuel"], e["kg"], e["cost"], e["co2"]] for e in P["stops"]]))
    if kind in ("all", "fuel"):
        f = P["fuel"]; sh.append(("Fuel & GHG (today)", [["Item", "Value", "Unit"], ["LDO", round(f["ldo"]), "kg"], ["Propane", round(f["prop"]), "kg"], ["Met coke", round(f["coke"], 2), "t"], ["Fuel cost", round(f["cost"]), S["cur"]], ["Scope 1", round(f["s1"] / 1000, 2), "tCO2e"], ["Scope 2 (process units)", round(f["s2"] / 1000, 2), "tCO2e"], ["Emission factors are SAMPLE values", "", ""]]))
    if kind in ("all", "meters"):
        sh.append(("Meters", [["Sr", "Location", "Feeder", "Make", "Status", "kW", "V LL", "I avg", "PF", "Hz", "kWh today"]] + [[m.sr, m.loc, m.name, m.make, "NO METER" if m.nometer else m.status] + ([round(m.v["tot"]["p"], 2), round(m.v["avg"]["vll"], 1), round(m.v["avg"]["i"], 2), round(m.v["pft"], 3), round(m.v["f"], 2), round(m.td, 1)] if m.v and not m.nometer else [None] * 6) for m in METERS]))
    if kind in ("all", "campaign"):
        T = STATE.get("tod") or {}; tp = CFG["settings"]["tod"]; z = [0, 0]
        sh.append(("Tariff today", [["Period", "From h", "To h", "Rate", "kWh", "Cost"]] + [[t[2], t[0], t[1], t[3], round((T.get("p", {}).get(str(i)) or z)[0], 1), round((T.get("p", {}).get(str(i)) or z)[1])] for i, t in enumerate(tp)]))
        sh.append(("Shifts today", [["Shift", "Hours", "kWh", "Cost"]] + [[k, h, round((T.get("sh", {}).get(k) or z)[0], 1), round((T.get("sh", {}).get(k) or z)[1])] for k, h in (("A", "06-14"), ("B", "14-22"), ("C", "22-06"))]))
        sh.append(("Ideas", [["ID", "Title", "Dept", "Category", "State", "By", "Est kW", "Est cost", "Digital/AI", "Verified kW", "Verified kWh/day"]] + [[i["id"], i["title"], i["dept"], i["cat"], i["state"], i["by"], i["est_kw"], i["est_cost"], "Yes" if i["digital"] else "", i["ver_kw"], i["ver_kwh"]] for i in EVT["ideas"]]))
        sh.append(("Waste reports", [["ID", "Time", "Dept", "Category", "Meter", "Report", "State", "Assignee", "Est kW", "Verified kW"]] + [[w["id"], ts(w["t"]), w.get("dept"), w.get("cat"), w["name"], w["text"], w["state"], w["assignee"], w.get("est_kw"), w.get("verified_kw")] for w in EVT["waste"]]))
    sh.append(("Notes", [["Generated", ts(now)], ["Data source", "Meters/process tags marked SIM are generated demo values until live data arrives"], ["Tariff, fuel prices and emission factors are sample values unless set in Energy & Cost"]]))
    return xlsx_bytes(sh)

