# ---------------------------------------------------------------- peak demand (15-minute block projection)
def md_tick(now, dt):
    s = BYSR.get(1)
    if not s or not s.v or s.status == "OFFLINE": return
    kw = s.v["tot"]["p"]; blk = int(now // 900) * 900
    if MD["blk"] != blk:
        if MD["blk"] and MD["full"]:
            avg = MD["e"] / .25; MD["last"] = avg; mo = datetime.date.fromtimestamp(MD["blk"]).strftime("%Y-%m")
            if MD["max"]["m"] != mo: MD["max"] = {"kw": 0.0, "t": 0, "m": mo}
            if avg > MD["max"]["kw"]: MD["max"].update(kw=avg, t=MD["blk"])
        MD["blk"] = blk; MD["e"] = kw * (now - blk) / 3600; MD["full"] = (now - blk) < 30
    T = STATE.setdefault("tod", {}); today = datetime.date.today().isoformat()
    if T.get("d") != today: T.clear(); T.update(d=today, p={}, sh={})
    r = rate_now(); idx = str(CFG["settings"]["tod"].index(r)); h = datetime.datetime.now().hour; sh = "A" if 6 <= h < 14 else "B" if 14 <= h < 22 else "C"
    for grp, k in ((T["p"], idx), (T["sh"], sh)):
        a = grp.setdefault(k, [0.0, 0.0]); a[0] += kw * dt / 3600; a[1] += kw * dt / 3600 * r[3]
    MD["e"] += kw * dt / 3600; rem = blk + 900 - now; MD["rem"] = rem
    MD["proj"] = (MD["e"] + kw * rem / 3600) / .25

def md_view():
    s = BYSR.get(1)
    return {"proj": MD["proj"], "rem": MD["rem"], "last": MD["last"], "max": MD["max"], "limit": CFG["settings"]["dlim"], "kw": s.v["tot"]["p"] if s and s.v else None}

def md_finding(H, now):
    S = CFG["settings"]; p = MD["proj"]
    if p is None or not MD["full"]: return
    lim = S["dlim"]
    if p > .95 * lim:
        fnd(H, "PEAK_MD", "Peak demand", "Site incomer (Main 132 kV)", 2 if p > lim else 1, "Projected 15-minute demand near or above the limit",
            "Projected %.0f kW for this block against a %.0f kW limit; %.0f s left in the block." % (p, lim, MD["rem"]),
            "Several large loads running together", "Defer or stagger flexible loads for the rest of this block (see Planning → Load scheduler). Production and safety needs come first.", "Demand",
            conf="Medium (linear projection of the running block)", risk="Low", metric={"n": "Projected demand", "v": p, "u": "kW"})

# ---------------------------------------------------------------- idle detection for metered motor-type feeders
def meter_findings(H, now):
    S = CFG["settings"]; today = datetime.date.today().isoformat()
    for m in METERS:
        if m.nometer or not m.v or m.status in ("OFFLINE", "STANDBY") or not MOTORRE.search(m.name): continue
        kw = m.v["tot"]["p"]; st = IDLE.get(m.sr)
        if not st: st = IDLE[m.sr] = {"typ": m.base if not m.ever_real else kw, "since": None, "kwh": 0.0, "day": today, "n": 0, "t": now}
        dt = max(0.0, min(15.0, now - st["t"])); st["t"] = now; st["n"] += 1
        if st["day"] != today: st["day"], st["kwh"] = today, 0.0
        st["typ"] = max(kw, st["typ"] * .9995)
        learned = (not m.ever_real) or st["n"] >= 720        # real meters: learn the typical load for ~1 hour first
        low = learned and .03 * max(m.rated, 1) < kw < S["idle_pct"] / 100 * st["typ"]
        if low:
            if st["since"] is None: st["since"] = now
            st["kwh"] += kw * dt / 3600
            held = now - st["since"]
            if held >= S["idle_min"] * 60:
                fnd(H, "IDLE_M%d" % m.sr, "Idle running", "%s (%s)" % (m.name, m.loc[:22]), 1, "Equipment running far below its normal load",
                    "%.0f kW now against a typical %.0f kW (%.0f %%) for %.0f min; %.1f kWh drawn while idle today." % (kw, st["typ"], kw / st["typ"] * 100, held / 60, st["kwh"]),
                    "No-load / idle running or standby equipment left on", "Check with operations; stop or put on standby if the process allows. Essential standby equipment should be excluded.", "KPI 5",
                    kwh=st["kwh"], conf="Medium (measured today; confirm with operations)", risk="Low–Medium", metric={"n": "Load", "v": kw, "u": "kW"})
        else: st["since"] = None

def reset_baselines():
    B = EVT["base"]; B["air_set"] = tg("AIR_SET"); B["so2_dp"] = tg("SO2_PDIS") - tg("SO2_PSUC"); B["so2_i"] = tg("SO2_I") / max(tg("SO2B_FLOW"), 1) * 1e5
    for b in BURNERS:
        fl = tg(b[0] + "_FLOW")
        if fl > 1: B["nz_" + b[0]] = tg(b[0] + "_OILP") / (fl * fl)
    B.pop("idle", None); save_evt()

# ---------------------------------------------------------------- Modbus TCP pollers (one thread per gateway / host)
PTYPES = {"f32": (2, ">f"), "f64": (4, ">d"), "u16": (1, ">H"), "i16": (1, ">h"), "u32": (2, ">I"), "i32": (2, ">i"), "u64": (4, ">Q")}

def read_generic(s, tid, unit, c):
    """Register-map driver. Config: blocks=[[start,count],...], map={name:{a,t,s}}, fc=3|4, word_order=big|little."""
    regs = {}
    for a, n in c["blocks"]:
        for i, x in enumerate(mb_read(s, tid, unit, int(a), int(n), int(c.get("fc", 3)))): regs[int(a) + i] = x
    def val(p):
        n, f = PTYPES[p["t"]]; w = [regs[p["a"] + k] for k in range(n)]
        if c.get("word_order") == "little": w = w[::-1]
        return struct.unpack(f, struct.pack(">%dH" % n, *w))[0] * p.get("s", 1)
    g = {}
    for k, p in c["map"].items():
        try:
            v = val(p); g[k] = v if math.isfinite(v) else None
        except Exception: g[k] = None
    tri = lambda k: [g.get(k + str(j)) for j in (1, 2, 3)]
    vll, vln, I, P, Q, S, PF, TV, TI = (tri(k) for k in ("vll", "vln", "i", "p", "q", "s", "pf", "thdv", "thdi"))
    if None in vll and None not in vln: vll = [x * 1.732 for x in vln]
    if None in vln and None not in vll: vln = [x / 1.732 for x in vll]
    if None in vll: raise ValueError("no voltage in map")
    z = lambda a: [x or 0.0 for x in a]
    P, Q, S, I, PF, TV, TI = z(P), z(Q), z(S), z(I), z(PF), z(TV), z(TI)
    tp = g.get("kw"); tp = sum(P) if tp is None else tp
    tq = g.get("kvar"); tq = sum(Q) if tq is None else tq
    ts = g.get("kva"); ts = (sum(S) if sum(S) else math.hypot(tp, tq)) if ts is None else ts
    if not any(P) and tp: P = [tp / 3] * 3
    pft = g.get("pft"); pft = (tp / ts if ts else 0.0) if pft is None else pft
    return dict(vll=vll, vln=vln, i=I, p=P, q=Q, s=S, pf=PF, thdv=TV, thdi=TI, f=g.get("f") or 0.0, pft=pft, tot=dict(p=tp, q=tq, s=ts),
                avg=dict(vll=sum(vll) / 3, vln=sum(vln) / 3, i=sum(I) / 3), e=dict(kwh=g.get("kwh")))

class GroupPoller(threading.Thread):
    daemon = True
    def __init__(self, host, port, cfgs):
        super().__init__(name="modbus-%s:%s" % (host, port)); self.host, self.port, self.cfgs, self.tid = host, port, cfgs, 0
    def one(self, s, c):
        self.tid += 1; u = int(c.get("unit", 1)); rt = RT.setdefault(c["sr"], {})
        if c.get("driver", "pac3200") == "generic": return read_generic(s, self.tid, u, c)
        n = rt.get("n", 0); main = mb_read(s, self.tid, u, 1, 56)
        if n % 5 == 0:
            rt["pft"] = f32(mb_read(s, self.tid + 1, u, 69, 2), 0)
            e = mb_read(s, self.tid + 2, u, 801, 4); d = struct.unpack(">d", struct.pack(">HHHH", *e))[0]
            if math.isfinite(d): rt["kwh"] = d / 1000
        rt["n"] = n + 1
        return parse_pac3200(main, rt.get("pft") or 0.0, rt.get("kwh"), c)
    def run(self):
        s = None; cyc = 1.0 if len(self.cfgs) == 1 else float(self.cfgs[0].get("cycle", 5))
        while True:
            try:
                s = socket.create_connection((self.host, self.port), timeout=2); s.settimeout(2)
                while True:
                    t0 = time.time()
                    for c in self.cfgs:
                        rt = RT.setdefault(c["sr"], {})
                        if time.time() < rt.get("next", 0): continue
                        try: v = self.one(s, c)
                        except socket.timeout:
                            rt["fail"] = rt.get("fail", 0) + 1; rt["next"] = time.time() + (0 if rt["fail"] < 3 else 30); raise Resync()
                        except (ConnectionError, OSError): raise
                        except Exception:
                            rt["fail"] = rt.get("fail", 0) + 1; rt["next"] = time.time() + (0 if rt["fail"] < 3 else 30); continue
                        rt["fail"] = 0; m = BYSR[c["sr"]]
                        with LOCK:
                            m.real_v, m.real_ts = v, time.time()
                            if not m.ever_real: audit("system", "Meter %s (%s) switched SIMULATED -> LIVE" % (c["sr"], m.name))
                            m.ever_real = True
                        if len(self.cfgs) > 1: time.sleep(.02)
                    time.sleep(max(.2, cyc - (time.time() - t0)))
            except Resync:
                try: s.close()
                except Exception: pass
                time.sleep(.2)
            except Exception:
                try: s.close()
                except Exception: pass
                time.sleep(5)

def start_pollers():
    groups = {}
    for c in CFG["live_meters"]:
        if c.get("enabled", True) and c["sr"] in BYSR:
            BYSR[c["sr"]].cfg = c; groups.setdefault((c["ip"], int(c.get("port", 502))), []).append(c)
    for (h, p), L in groups.items(): GroupPoller(h, p, L).start()

# ---------------------------------------------------------------- ingest API (DCS / PI / SCADA / MIS push)
def ingest(h):
    ip = h.ip(); now = time.time(); key = "ing" + ip
    with LOCK:
        f = FAILS.get(key, [0, 0])
        if now < f[1]: return h.send(429, '{"err":"too many attempts"}')
    tok = h.headers.get("X-Ingest-Token", "")
    if not hmac.compare_digest(tok.encode(), str(CFG.get("ingest_token", "!")).encode()):
        with LOCK:
            f[0] += 1
            if f[0] >= 5: f = [0, now + 60]
            FAILS[key] = f
        audit("ingest", "bad token", ip); return h.send(401, '{"err":"bad token"}')
    FAILS.pop(key, None)
    try:
        n = int(h.headers.get("Content-Length") or 0)
        if n > 65536: return h.send(413, '{"err":"too large"}')
        d = json.loads(h.rfile.read(n) or b"{}"); tags = d.get("tags") or {}
        assert isinstance(tags, dict)
    except Exception: return h.send(400, '{"err":"bad request"}')
    ok, unk = 0, []
    with LOCK:
        for k, v in list(tags.items())[:INGEST_MAX]:
            if k in TAGS and isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v): TAGS[k]["rv"] = float(v); TAGS[k]["rts"] = now; ok += 1
            else: unk.append(str(k)[:40])
        if now - TICKST.get("ing", 0) > 300: audit("ingest", "%d tags accepted" % ok, ip)
        TICKST["ing"] = now
    h.send(200, json.dumps({"ok": True, "accepted": ok, "unknown": unk[:10]}))

# ---------------------------------------------------------------- extra routes
def _q(h): return parse_qs(urlparse(h.path).query)

def ext_get(h, p, s):
    if p == "/api/plant": h.send(200, PSNAP[0]); return True
    if p == "/api/forecast":
        try: h.send(200, json.dumps(forecast()))
        except Exception: h.send(500, '{"err":"forecast failed"}')
        return True
    if p == "/api/profile":
        q = _q(h); i = (q.get("id") or ["M1"])[0]
        try: hrs = max(1, min(720, int((q.get("hours") or ["24"])[0])))
        except Exception: hrs = 24
        if not re.fullmatch(r"[AM][A-Za-z0-9]{1,12}", i): h.send(400, '{"err":"bad id"}'); return True
        h.send(200, json.dumps(db_profile(i, hrs))); return True
    if p == "/api/report.xlsx":
        k = (_q(h).get("type") or ["all"])[0]
        if k not in ("all", "energy", "kpi", "actions", "stoppages", "fuel", "meters", "campaign"): h.send(400, '{"err":"bad type"}'); return True
        with LOCK: body = report_xlsx(k)
        audit(s["u"], "report downloaded: " + k, h.ip())
        h.send(200, body, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", extra={"Content-Disposition": 'attachment; filename="vidyut_%s_%s.xlsx"' % (k, datetime.date.today().isoformat())}); return True
    if p == "/api/waste": h.send(200, json.dumps(EVT["waste"][-100:][::-1])); return True
    if p == "/api/ideas": h.send(200, json.dumps(EVT["ideas"][-300:][::-1])); return True
    if p == "/api/waste/photo":
        i = (_q(h).get("id") or [""])[0]
        if not re.fullmatch(r"W\d{1,6}", i) or not os.path.exists(os.path.join(PHOTO_DIR, i + ".jpg")): h.send(404, '{"err":"none"}'); return True
        h.send(200, open(os.path.join(PHOTO_DIR, i + ".jpg"), "rb").read(), "image/jpeg"); return True

    return False

def ext_post(h, p, d, s):
    u, role = s["u"], s["role"]; ip = h.ip(); now = time.time(); bad = lambda c=400, m="bad request": h.send(c, json.dumps({"err": m}))
    if p == "/api/action":
        if not can_decide(role): bad(403, "Not allowed for your role"); return True
        i = str(d.get("id", ""))[:40]; dec = d.get("decision"); why = str(d.get("reason") or "")[:300]
        with LOCK:
            f = FIND.get(i); a = EVT["actions"].get(i)
            if dec == "implement":
                if not a or a.get("status") != "Approved": bad(400, "Only approved items can be marked implemented"); return True
                a.update(status="Implemented", impl_by=u, impl_at=now)
            elif dec in ("approve", "reject"):
                if not f and not a: bad(404, "Unknown item"); return True
                a = EVT["actions"].setdefault(i, {"first": now})
                a.update(status="Approved" if dec == "approve" else "Rejected", by=u, reason=why, at=now, base_metric=dict(f["metric"]) if f and f.get("metric") else None)
            else: bad(); return True
            save_evt()
        audit(u, "recommendation %s %s%s" % (i, dec, (": " + why) if why else ""), ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/ack":
        if not can_edit(role): bad(403, "Not allowed for your role"); return True
        i = str(d.get("id", ""))[:40]
        with LOCK: EVT["acks"][i] = {"by": u, "at": now}; save_evt()
        audit(u, "finding acknowledged " + i, ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/baseline":
        if role != "admin": bad(403, "Administrators only"); return True
        with LOCK: reset_baselines()
        audit(u, "KPI baselines reset", ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/stoppage":
        if not can_edit(role): bad(403, "Not allowed for your role"); return True
        try:
            pl = d["plant"]; assert pl in PLANTS; st = float(d["start"]); en = d.get("end"); en = float(en) if en else None
            assert 1e9 < st < now + 86400 and (en is None or st < en < now + 86400)
        except Exception: bad(); return True
        with LOCK: EVT["stops"].append({"id": "S%d" % (len(EVT["stops"]) + 1), "plant": pl, "start": st, "end": en, "cause": str(d.get("cause") or "")[:120], "src": "MANUAL", "by": u}); save_evt()
        audit(u, "stoppage recorded: " + PNAME[pl], ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/waste":
        t = str(d.get("text") or "").strip()[:300]; sr = d.get("sr")
        if not t: bad(); return True
        sr = int(sr) if isinstance(sr, (int, float)) and int(sr) in BYSR else None
        cat = d.get("cat") if d.get("cat") in WCATS else "Other energy-saving suggestion"; dept = d.get("dept") if d.get("dept") in DEPTS else "Other"
        try: ek = max(0.0, min(1e5, float(d.get("est_kw") or 0)))
        except Exception: ek = 0.0
        with LOCK:
            wid = "W%d" % (len(EVT["waste"]) + 1); ph = False
            if d.get("photo"):
                try:
                    pre, b64 = str(d["photo"]).split(",", 1); assert pre == "data:image/jpeg;base64" and len(b64) < 240000
                    raw = base64.b64decode(b64, validate=True); assert raw[:3] == b"\xff\xd8\xff"
                    os.makedirs(PHOTO_DIR, exist_ok=True); open(os.path.join(PHOTO_DIR, wid + ".jpg"), "wb").write(raw); ph = True
                except Exception: bad(400, "Photo must be a small JPEG"); return True
            EVT["waste"].append({"id": wid, "t": now, "sr": sr, "name": BYSR[sr].name if sr else "", "loc": BYSR[sr].loc if sr else "", "text": t, "by": u, "state": "Open", "assignee": "", "note": "", "cat": cat, "dept": dept, "est_kw": ek, "photo": ph}); save_evt()
        audit(u, "waste report filed" + (" (meter %s)" % sr if sr else ""), ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/waste/update":
        if not can_edit(role): bad(403, "Not allowed for your role"); return True
        with LOCK:
            w = next((x for x in EVT["waste"] if x["id"] == str(d.get("id"))), None)
            if not w: bad(404, "Unknown report"); return True
            if d.get("state") in WSTATES:
                if d["state"] == "Verified" and not can_decide(role): bad(403, "Verification needs a manager role"); return True
                w["state"] = d["state"]
            if "assignee" in d: w["assignee"] = str(d["assignee"])[:60]
            if "note" in d: w["note"] = str(d["note"])[:200]
            if d.get("verified_kw") not in (None, ""):
                try: w["verified_kw"] = max(0.0, min(1e5, float(d["verified_kw"])))
                except Exception: pass
            if w["state"] in ("Verified", "Closed"): w["closed"] = now
            save_evt()
        audit(u, "waste report %s -> %s" % (w["id"], w["state"]), ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/idea":
        t = str(d.get("title") or "").strip()[:100]
        if not t: bad(); return True
        try: ek = max(0.0, min(1e5, float(d.get("est_kw") or 0))); ec = max(0.0, min(1e10, float(d.get("est_cost") or 0)))
        except Exception: bad(); return True
        with LOCK:
            EVT["ideas"].append({"id": "I%d" % (len(EVT["ideas"]) + 1), "t": now, "title": t, "desc": str(d.get("desc") or "")[:300], "dept": d.get("dept") if d.get("dept") in DEPTS else "Other",
                                 "cat": d.get("cat") if d.get("cat") in WCATS else "Other energy-saving suggestion", "est_kw": ek, "est_cost": ec, "digital": bool(d.get("digital")), "state": "Submitted", "by": u, "owner": "", "act_cost": None, "ver_kw": None, "ver_kwh": None}); save_evt()
        audit(u, "idea submitted: " + t[:40], ip); h.send(200, '{"ok":true}'); return True
    if p == "/api/idea/update":
        if not can_decide(role): bad(403, "Not allowed for your role"); return True
        with LOCK:
            w = next((x for x in EVT["ideas"] if x["id"] == str(d.get("id"))), None)
            if not w: bad(404, "Unknown idea"); return True
            if d.get("state") in ISTATES: w["state"] = d["state"]
            if "owner" in d: w["owner"] = str(d["owner"])[:60]
            if "digital" in d: w["digital"] = bool(d["digital"])
            for k_ in ("act_cost", "ver_kw", "ver_kwh"):
                if d.get(k_) not in (None, ""):
                    try: w[k_] = max(0.0, min(1e10, float(d[k_])))
                    except Exception: pass
            if w["state"] == "Verified" and w.get("ver_kw") is None: bad(400, "Enter the measured kW reduction to verify"); return True
            save_evt()
        audit(u, "idea %s -> %s" % (w["id"], w["state"]), ip); h.send(200, '{"ok":true}'); return True
    return False

# ---------------------------------------------------------------- backup
def backup():
    name = os.path.join(HOME, "vidyut_backup_%s.zip" % datetime.datetime.now().strftime("%Y%m%d_%H%M%S")); tmp = DB_PATH + ".bak"
    with zipfile.ZipFile(name, "w", zipfile.ZIP_DEFLATED) as z:
        for pth in (CFG_PATH, AUDIT_PATH, STATE_PATH, HIST_PATH, EVT_PATH):
            if os.path.exists(pth): z.write(pth, os.path.basename(pth))
        if os.path.exists(DB_PATH):
            a = sqlite3.connect(DB_PATH); b = sqlite3.connect(tmp); a.backup(b); b.close(); a.close(); z.write(tmp, os.path.basename(DB_PATH)); os.remove(tmp)
    print("Backup written: %s\n(contains password hashes and the ingest token - store it securely; restore by unzipping into the VIDYUT folder)" % name)

# ------------------------------------------------------------------ HTTP
SESS, FAILS = {}, {}
MAXBODY = 16384

class H(http.server.BaseHTTPRequestHandler):
    server_version = "VIDYUT"; sys_version = ""
    def log_message(self, *a): pass
    def ip(self): return self.client_address[0]

    def sess(self):
        c = SimpleCookie(self.headers.get("Cookie", "")); k = c.get("vd_sid")
        if not k: return None
        with LOCK:
            s = SESS.get(k.value); now = time.time()
            if not s: return None
            if now - s["last"] > CFG["idle_minutes"] * 60 or now - s["t0"] > CFG["session_hours"] * 3600:
                SESS.pop(k.value, None); audit(s["u"], "session expired", s["ip"]); return None
            s["last"] = now; s["sid"] = k.value; return s

    def send(self, code, body, ctype="application/json", extra=None, nonce=None):
        if isinstance(body, str): body = body.encode()
        self.send_response(code); self.send_header("Content-Type", ctype + ("; charset=utf-8" if "text" in ctype or "json" in ctype else ""))
        self.send_header("Content-Length", str(len(body))); self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff"); self.send_header("Referrer-Policy", "no-referrer"); self.send_header("X-Frame-Options", "DENY")
        self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'nonce-%s'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'" % (nonce or "x"))
        if CFG.get("tls_cert"): self.send_header("Strict-Transport-Security", "max-age=31536000")
        for k, v in (extra or {}).items(): self.send_header(k, v)
        self.end_headers(); self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("Content-Length") or 0)
        if n > (262144 if self.path.startswith("/api/waste") else MAXBODY): raise ValueError("too large")
        return json.loads(self.rfile.read(n) or b"{}")

    def do_GET(self):
        p = self.path.split("?")[0]; s = self.sess()
        if p == "/healthz": return self.send(200, '{"ok":true}')
        if p == "/":
            nonce = secrets.token_urlsafe(12)
            if not s: return self.send(200, LOGIN_HTML.replace("__NONCE__", nonce), "text/html", nonce=nonce)
            boot = json.dumps({"user": s["u"], "role": s["role"], "settings": CFG["settings"], "live": [c["sr"] for c in CFG["live_meters"] if c.get("enabled", True)],
                               "warn": s.get("warn", False), "ingest": CFG.get("ingest_token") if s["role"] == "admin" else None,
                               "smtp_on": bool((CFG.get("smtp") or {}).get("enabled"))}, ensure_ascii=False).replace("<", "\\u003c")
            return self.send(200, APP_HTML.replace("/*HIST*/{dates:[],A:{},F:{}}", history_text()).replace("/*BOOT*/{}", boot).replace("__NONCE__", nonce), "text/html", nonce=nonce)
        if not s: return self.send(401, '{"err":"auth"}')
        if ext_get(self, p, s): return
        if p == "/api/live": return self.send(200, SNAP[0])
        if p == "/api/history": return self.send(200, history_text())
        if p == "/api/audit":
            if s["role"] != "admin": return self.send(403, '{"err":"forbidden"}')
            return self.send(200, json.dumps(RECENT[:100]))
        self.send(404, '{"err":"not found"}')

    def do_POST(self):
        p = self.path.split("?")[0]
        if p == "/api/ingest": return ingest(self)
        if self.headers.get("X-VD") != "1": return self.send(403, '{"err":"csrf"}')
        try: d = self.body()
        except Exception: return self.send(400, '{"err":"bad request"}')
        if p == "/api/login": return self.login(d)
        s = self.sess()
        if not s: return self.send(401, '{"err":"auth"}')
        if p == "/api/logout":
            with LOCK: SESS.pop(s["sid"], None)
            audit(s["u"], "sign-out", self.ip())
            return self.send(200, '{"ok":true}', extra={"Set-Cookie": "vd_sid=; Max-Age=0; Path=/; HttpOnly; SameSite=Strict"})
        if ext_post(self, p, d, s): return
        if p == "/api/config":
            if s["role"] != "admin": return self.send(403, '{"err":"forbidden"}')
            try:
                n = d["settings"]; tod = [[float(a), float(b), str(c)[:20], float(r)] for a, b, c, r in n["tod"]][:8]
                new = dict(CFG["settings"]); new.update(cur=str(n["cur"])[:4], ef=float(n["ef"]), pfmin=float(n["pfmin"]), dlim=float(n["dlim"]), tod=tod)
                for k in NUMKEYS:
                    if k in n: new[k] = float(n[k]); assert 0 <= new[k] <= 1e6
                assert 0 <= new["ef"] <= 2 and .5 <= new["pfmin"] <= 1 and new["dlim"] > 0 and all(0 <= t[0] < t[1] <= 24 and 0 <= t[3] < 1000 for t in tod) and new["o2_lo"] < new["o2_hi"] < 21
            except Exception: return self.send(400, '{"err":"invalid settings"}')
            with LOCK:
                old = CFG["settings"]; CFG["settings"] = new; save_config(CFG)
            audit(s["u"], "settings changed: " + ", ".join(k for k in new if new[k] != old.get(k)), self.ip())
            return self.send(200, '{"ok":true}')
        self.send(404, '{"err":"not found"}')

    def login(self, d):
        u, pw, ip = str(d.get("u", ""))[:64], str(d.get("p", ""))[:256], self.ip(); key = ip; now = time.time()
        with LOCK:
            f = FAILS.get(key, [0, 0])
            if now < f[1]: return self.send(429, json.dumps({"err": "Too many attempts - wait %ds" % (f[1] - now)}))
            usr = CFG["users"].get(u); ok = check_pw(pw, usr["hash"] if usr else hash_pw("x", 1000))
            if usr and ok:
                FAILS.pop(key, None); sid = secrets.token_urlsafe(32)
                warn = pw == DEFAULT_PASS.get(u)
                SESS[sid] = {"u": u, "role": usr["role"], "ip": ip, "t0": now, "last": now, "warn": warn}
                audit(u, "sign-in OK", ip)
                ck = "vd_sid=%s; Path=/; HttpOnly; SameSite=Strict%s" % (sid, "; Secure" if CFG.get("tls_cert") else "")
                return self.send(200, json.dumps({"ok": True}), extra={"Set-Cookie": ck})
            f[0] += 1
            if f[0] >= 5: f = [0, now + 60]
            FAILS[key] = f
        audit(u[:32] or "?", "sign-in FAILED", ip); time.sleep(.4)
        self.send(401, json.dumps({"err": "Invalid credentials"}))

class Server(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True; allow_reuse_address = True

# ------------------------------------------------------------------ main
def main():
    global CFG
    ap = argparse.ArgumentParser(); ap.add_argument("--passwd"); ap.add_argument("--adduser", nargs=2, metavar=("NAME", "ROLE"))
    ap.add_argument("--import-xlsx"); ap.add_argument("--backup", action="store_true"); ap.add_argument("--verify-audit", action="store_true"); a = ap.parse_args()
    CFG = load_config()
    if a.verify_audit: sys.exit(verify_audit())
    if a.import_xlsx: return import_xlsx(a.import_xlsx)
    if a.backup: return backup()
    if a.passwd or a.adduser:
        name = a.passwd or a.adduser[0]
        if a.adduser:
            if a.adduser[1] not in ROLES: sys.exit("role must be one of: " + ", ".join(ROLES))
            CFG["users"].setdefault(name, {"role": a.adduser[1], "hash": ""})
        if name not in CFG["users"]: sys.exit("no such user")
        pw = getpass.getpass("New password for %s: " % name)
        if len(pw) < 10 or pw != getpass.getpass("Repeat: "): sys.exit("Password must be at least 10 characters and match.")
        CFG["users"][name]["hash"] = hash_pw(pw); save_config(CFG); audit("cli", "password set for " + name); return print("Saved.")
    init_audit(); load_state(); load_evt(); db_init(); start_pollers()
    threading.Thread(target=tick_loop, daemon=True).start(); time.sleep(.3)
    srv = Server((CFG["host"], int(CFG["port"])), H)
    if CFG.get("tls_cert"):
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); ctx.minimum_version = ssl.TLSVersion.TLSv1_2
        ctx.load_cert_chain(CFG["tls_cert"], CFG["tls_key"]); srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
    audit("system", "server started"); proto = "https" if CFG.get("tls_cert") else "http"
    print("VIDYUT running at %s://%s:%s   (Ctrl+C to stop)" % (proto, "localhost" if CFG["host"] in ("0.0.0.0", "") else CFG["host"], CFG["port"]))
    if any(check_pw(p, CFG["users"][u]["hash"]) for u, p in DEFAULT_PASS.items() if u in CFG["users"]):
        print("WARNING: default passwords are in use - run: python vidyut.py --passwd admin")
    if not CFG.get("tls_cert"): print("NOTE: plain HTTP. Use HTTPS (tls_cert/tls_key in vidyut_config.json) outside a closed network.")
    try: srv.serve_forever()
    except KeyboardInterrupt: audit("system", "server stopped")

if __name__ == "__main__":
    main()
